package platform

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"syscall"

	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/config"
)

// Source selection permits a nonempty project directory, not entire homes or private runtime trees.
func ValidateSourcePath(source, mountRoot, home string) error {
	if !config.AbsolutePath(source) || !config.AbsolutePath(mountRoot) || source == home || config.Within(source, home) || config.Overlap(source, mountRoot) {
		return errors.New("source cannot be root/home/ancestor of home or overlap the mount target")
	}
	for _, root := range []string{"/etc", "/var/lib/autobyteus-nfs", "/var/lib/docker", "/var/run", "/var/tmp", "/private", "/System", "/Library", "/bin", "/sbin", "/usr", "/proc", "/sys", "/dev", "/run", "/tmp"} {
		if config.Within(root, source) {
			return fmt.Errorf("system/private/ephemeral source is not supported: %s", source)
		}
	}
	for _, part := range strings.Split(source, string(filepath.Separator)) {
		switch part {
		case ".autobyteus", ".codex", ".claude", ".grok", ".gemini", ".ssh", ".docker", ".config", "Library":
			return errors.New("private application or authentication tree cannot be exported")
		}
	}
	if strings.ContainsAny(source, `"\\`) {
		return errors.New("source contains unsupported export-path quoting")
	}
	return nil
}
func SourceIdentity(source string) (config.Identity, error) {
	info, err := os.Lstat(source)
	if err != nil {
		return config.Identity{}, err
	}
	if !info.IsDir() {
		return config.Identity{}, errors.New("source must be a real directory, not a symlink")
	}
	canonical, err := filepath.EvalSymlinks(source)
	if err != nil {
		return config.Identity{}, err
	}
	if canonical != source {
		return config.Identity{}, errors.New("choose canonical source path without symlink ancestors")
	}
	st := info.Sys().(*syscall.Stat_t)
	return config.Identity{Device: uint64(st.Dev), Inode: st.Ino}, nil
}
func CheckSource(h config.HostedFilesystem) error {
	id, err := SourceIdentity(h.Source)
	if err != nil {
		return err
	}
	if id != h.Identity {
		return errors.New("selected source device/inode changed; no replacement will be exported")
	}
	return QualifyFilesystem(h.Source)
}

package config

import (
	"errors"
	"runtime"
	"strings"
)

type Identity struct {
	Device uint64 `json:"device"`
	Inode  uint64 `json:"inode"`
}
type HostedFilesystem struct {
	InstallationID string   `json:"installationId"`
	StorageID      string   `json:"storageId"`
	Source         string   `json:"source"`
	Identity       Identity `json:"identity"`
	Backend        string   `json:"backend"`
	DataUID        uint32   `json:"dataUid"`
	DataGID        uint32   `json:"dataGid"`
	Allowlist      []string `json:"allowlist"`
	// Immutable release engine identity, never latest or an unbounded upgrade.
	EngineImage string `json:"engineImage,omitempty"`
}
type Attachment struct {
	Connection
	InstallationID string   `json:"installationId"`
	UserUID        uint32   `json:"userUid"`
	UserGID        uint32   `json:"userGid"`
	Nodes          []string `json:"nodes"`
}

// NodeAttachment is nonsecret and published only for an explicitly opted-in node.
type NodeAttachment struct {
	DaemonID            string `json:"daemonId"`
	StorageID           string `json:"storageId"`
	Node                string `json:"node"`
	MountRoot           string `json:"mountRoot"`
	Volume              string `json:"volume"`
	DescriptorDirectory string `json:"descriptorDirectory"`
}

func (h HostedFilesystem) Validate() error {
	if !ValidID(h.InstallationID) || !ValidID(h.StorageID) || !AbsolutePath(h.Source) || h.DataUID == 0 || h.DataGID == 0 {
		return errors.New("invalid hosted filesystem identity/source/nonroot owner")
	}
	if h.Backend != "apple" && h.Backend != "ganesha-native" && h.Backend != "ganesha-docker" {
		return errors.New("unsupported storage backend")
	}
	_, err := Allowlist(h.Allowlist)
	return err
}
func (a Attachment) Validate() error {
	if !ValidID(a.InstallationID) || a.UserUID == 0 || a.UserGID == 0 {
		return errors.New("attachment requires installation identity and nonroot user")
	}
	if len(a.Nodes) > 32 {
		return errors.New("select at most 32 managed nodes")
	}
	seen := map[string]bool{}
	for _, node := range a.Nodes {
		if seen[node] {
			return errors.New("duplicate selected node")
		}
		seen[node] = true
		if !ValidNode(node) {
			return errors.New("invalid selected node")
		}
	}
	return a.Connection.Validate()
}
func PrivateDirectory() string {
	if runtime.GOOS == "darwin" {
		return "/Library/Application Support/AutoByteusNFS"
	}
	return "/var/lib/autobyteus-nfs"
}
func BinaryPath() string {
	if runtime.GOOS == "darwin" {
		return "/Library/AutoByteusNFS/libexec/autobyteus-nfs"
	}
	return "/usr/libexec/autobyteus-nfs/autobyteus-nfs"
}

func (a NodeAttachment) Validate() error {
	if a.DaemonID == "" || strings.ContainsAny(a.DaemonID, "\r\n") || !ValidNode(a.Node) || !ValidID(a.StorageID) || !AbsolutePath(a.MountRoot) || strings.Contains(a.MountRoot, ",") || a.Volume != "autobyteus-nfs-"+a.StorageID || a.DescriptorDirectory != PublicDirectory {
		return errors.New("invalid selected-node attachment")
	}
	return nil
}

package setup

import (
	"errors"
	"os"

	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/backend"
	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/config"
	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/docker"
	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/platform"
	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/service"
)

func (s *Service) Reconnect(retryConsumed bool) error {
	var pending Plan
	if err := s.Store.Read("pending-setup.json", &pending); err == nil {
		return errors.New("setup incomplete; run reconnect interactively to review/resume")
	} else if !os.IsNotExist(err) {
		return err
	}
	a, h, err := s.CheckConfiguration()
	if err != nil {
		return err
	}
	if h != nil {
		if err = platform.CheckSource(*h); err != nil {
			return err
		}
		switch h.Backend {
		case "apple":
			var p backend.ApplePlan
			if err = s.Store.Read("apple-resource.json", &p); err != nil {
				return err
			}
			if err = backend.EnsureApple(s.Runner, p, a.Endpoint); err != nil {
				return err
			}
		case "ganesha-native":
			if err = backend.EnsureGanesha(s.Runner, *h, s.Store.Directory); err != nil {
				return err
			}
		case "ganesha-docker":
			if s.Docker == nil {
				return errors.New("storage Docker daemon unavailable")
			}
			if err = backend.VerifyGanesha(*h, s.Store.Directory, true); err != nil {
				return err
			}
			if err = s.Docker.EnsureEngine(*h, s.Store.Directory, false); err != nil {
				return err
			}
		}
	}
	var published config.Connection
	if e := s.Public.Read("attachment.json", &published); os.IsNotExist(e) {
		if e = s.Public.Write("attachment.json", a.Connection); e != nil {
			return e
		}
	} else if e != nil {
		return e
	} else if published != a.Connection {
		return errors.New("public descriptor was changed externally; refusing silent overwrite")
	}
	if err = platform.EnsureMount(s.Runner, a.Connection); err != nil {
		return err
	}
	if err = service.NonrootProbe(s.Binary, a.MountRoot, a.StorageID, a.UserUID, a.UserGID, false, s.Lock); err != nil {
		return err
	}
	return s.reconnectNodes(a, retryConsumed)
}
func (s *Service) Detach(consented bool) error {
	if !consented {
		return errors.New("detach declined; nothing changed")
	}
	a, h, err := s.CheckConfiguration()
	var pending Plan
	if os.IsNotExist(err) {
		if e := s.Store.Read("pending-setup.json", &pending); e != nil {
			return e
		}
		a, h = pending.Attachment, pending.Hosted
		if e := a.Validate(); e != nil {
			return e
		}
	} else if err != nil {
		return err
	}
	if h != nil && (h.Backend == "ganesha-native" || h.Backend == "ganesha-docker") {
		if err = backend.VerifyGaneshaForDetach(*h, s.Store.Directory, h.Backend == "ganesha-docker"); err != nil {
			return err
		}
	}
	if (len(a.Nodes) > 0 || (h != nil && h.Backend == "ganesha-docker")) && s.Docker == nil {
		return errors.New("selected Docker daemon unavailable; cannot safely detach nodes")
	}
	if err = s.detachNodes(a); err != nil {
		return err
	}
	// No force/unmount-as-cleanup. Busy means source/service/config remain available.
	if err = platform.Unmount(s.Runner, a.Connection); err != nil {
		return err
	}
	if err = platform.RemoveJob(s.Runner); err != nil {
		return err
	}
	if h != nil {
		switch h.Backend {
		case "apple":
			var p backend.ApplePlan
			if err = s.Store.Read("apple-resource.json", &p); os.IsNotExist(err) && pending.Apple != nil {
				p = *pending.Apple
			} else if err != nil {
				return err
			}
			note, e := backend.DetachApple(s.Runner, p)
			if e != nil {
				return e
			}
			if note != "" {
				if e = s.Store.Write("apple-detach-receipt.json", struct {
					Retained string `json:"retained"`
				}{note}); e != nil {
					return e
				}
			}
		case "ganesha-native":
			if err = backend.RemoveOwnedPackageMask(s.Runner, s.Store.Directory); err != nil {
				return err
			}
			if err = backend.DetachGanesha(s.Runner, s.Store.Directory); err != nil {
				return err
			}
		case "ganesha-docker":
			if err = s.Docker.DetachEngine(*h, s.Store.Directory); err != nil {
				return err
			}
		}
		if h.Backend != "apple" {
			if err = backend.RemoveGaneshaConfiguration(*h, s.Store.Directory, h.Backend == "ganesha-docker"); err != nil {
				return err
			}
		}
	}
	if err = s.Public.Remove("attachment.json"); err != nil {
		return err
	}
	for _, name := range []string{"attachment.json", "hosted-filesystem.json", "apple-resource.json", "docker-endpoint.json", "pending-setup.json"} {
		if err = s.Store.Remove(name); err != nil {
			return err
		}
	}
	for _, node := range a.Nodes {
		if err = docker.RemoveStartAttempt(s.Store, node); err != nil {
			return err
		}
	}
	// Source, marker, named volumes, recovery state and private recreation receipts are preserved.
	return nil
}

package service

import (
	"context"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/AutoByteus/autobyteus-workspace/autobyteus-nfs/internal/platform"
)

// Supervise owns a single serial administrative reconciliation. A stuck hard-NFS
// call stays outstanding; this is deliberately not an outage watchdog/process pool.
func Supervise(ctx context.Context, privateRoot string, log io.Writer, reconcile func(*os.File) error) error {
	for {
		lock, err := platform.Lock(privateRoot)
		if err == nil {
			err = reconcile(lock)
			lock.Close()
		}
		if err != nil {
			fmt.Fprintf(log, "AutoByteus NFS checking/incomplete: %v\n", err)
		}
		select {
		case <-ctx.Done():
			return nil
		case <-time.After(30 * time.Second):
		}
	}
}
